class BigResource {
    int* data;
public:
    // Lvalue Copy Constructor
    BigResource(const BigResource& other);

    // Rvalue Move Constructor (Stealing resources)
    BigResource(BigResource&& other) noexcept
    : data(std::exchange(other.data, nullptr)) {}

    // Rvalue Move Assignment
    BigResource& operator=(BigResource&& other) noexcept {
        if (this != &other) {
            delete[] data;
            data = std::exchange(other.data, nullptr);
        }
        return *this;
    }
};

