struct Point {
    int val = 0;
    // Lvalue ref qualifier: allows use on named objects
    int get_val() const & { return val; }

    // Rvalue ref qualifier: allows use on temporaries (prvalues)
    int get_val() && { return val + 100; }
};

Point p{10};
int lval_res = p.get_val();       // Calls & version (10)
int rval_res = Point{5}.get_val(); // Calls && version (105)
